mapper.update:
        UPDATE /* LGVATT40011.updateAttendanceResult */
               tb_att_result_n ar
        SET    time_and_attendance_code               = #{attendanceCode}
		     , time_attend_detail_code                = #{timeAttendDetailCode}
		     , work_start_time                        = #{workStartTime}
		     , tardy_hours                            = #{tardyHours}
		     , early_leave_hours                      = #{earlyLeaveHours}
		     , going_out_hours                        = #{goingOutHours}
		     , overtime_sum_hours                     = #{overtimeSumHours}
		     , time_attend_input_reason_desc          = #{timeAttendInputReasonDesc}
		     , evening_meal_flag                      = #{eveningMealFlag}
		     , normal_night_overtime_hours            = #{normalNightOvertimeHours}
		     , weekday_overtime_hours                 = #{weekdayOvertimeHours}
		     , holiday_overtime_hours                 = #{holidayOvertimeHours}
		     , public_holiday_overtime_hours          = #{publicHolidayOvertimeHours}
		     , weekday_night_overtime_hours           = #{weekdayNightOvertimeHours}
		     , weekday_ot_af_night_work_hours         = #{weekdayOtAfNightWorkHours}
		     , holiday_night_overtime_hours           = #{holidayNightOvertimeHours}
		     , public_holiday_night_ot_hours          = #{publicHolidayNightOtHours}
             , last_update_user_id                    = #{applicationUserId}
             , last_update_date                       = SYSDATE
             , base_time_attend_apply_flag            = 'N'
        WHERE  subsidiary_code                        = #{subsidiaryCode}
        AND    employee_no                            = #{employeeNo}
        AND    time_and_attendance_date               = TO_DATE(#{attendanceYyyymmddResult}, 'DDMMYYYY')
